310	impl BlockedPool {
311	    /// Returns true if there are NO blocked threads waiting outside the run-queue.
312	    fn is_empty(&self) -> bool {
313	        self.no_futex_waiters()
314	            && self.timed_waiters.is_empty()
315	            && self.child_waiters.is_empty()
316	            && self.physical_child_waiters.is_empty()
317	            && self.physical_child_ready.is_empty()
318	            && self.external_io_blockers.is_empty()
319	            && self.rt_sigsuspend_blockers.is_empty()
320	            && self.sigchld_deferred.is_empty()
321	    }
322	
323	    /// True if there are no runnable threads, and the only blocked ones are externally-blocked.
324	    fn only_external_blocked(&self) -> bool {
325	        let has_external_wait = !self.external_io_blockers.is_empty()
326	            || !self.child_waiters.is_empty()
327	            || !self.physical_child_waiters.is_empty();
328	        self.no_futex_waiters()
329	            && self.timed_waiters.is_empty()
330	            && self.physical_child_ready.is_empty()
331	            && (has_external_wait || !self.rt_sigsuspend_blockers.is_empty())
332	    }
333	
334	    /// Returns true if there are zero threads blocked on futexes.
335	    fn no_futex_waiters(&self) -> bool {
336	        self.futex_waiters.iter().all(|(_, v)| v.is_empty())
337	    }
338	}
339	
340	/// Validate a request made by a thread executing outside the runnable set.
341	/// A signal may interrupt a real blocking syscall before its ordinary
342	/// continuation request is posted, so an inbound-signal request is ready too.
343	/// `vfork` is excluded because a signal does not satisfy its child barrier.
344	fn blocking_request_is_ready(
345	    req: &Resources,
346	    expected: ExternalOpId,
347	    signal_can_complete: bool,
348	) -> bool {
349	    assert_eq!(req.resources.len(), 1);
350	    let rsrc = req.resources.iter().next().unwrap().0;
351	    match rsrc {
352	        ResourceID::BlockedExternalContinue(op_id) | ResourceID::VforkFailed(op_id) => {
353	            assert_eq!(*op_id, expected);
354	            true
355	        }
356	        ResourceID::InboundSignal(_) if signal_can_complete => true,
357	        other => panic!("expected external continue request, got {other:?}"),
358	    }
359	}
