799	    /// Internal helper. Add a [child] process to the tree, with the parent being `None`
800	    /// if it's the root of the tree.
801	    fn add_edge(&mut self, parent: Option<DetTid>, child: DetTid) {
802	        match parent {
803	            None => {
804	                self.root = Some(child);
805	                // Ensure an entry, even if the children vector is empty:
806	                let _vec = self.tree.entry(child).or_default();
807	            }
808	            Some(p) => {
809	                let vec = self.tree.entry(p).or_default();
810	                vec.push(child);
811	                let _vec = self.tree.entry(child).or_default();
812	            }
813	        }
814	    }
