        // AUTONOMOUS-BOT-IMPLEMENTED
        // TODO-HUMAN-REVIEW(#663)
        let live_process_thread = self
            .thread_tree
            .my_thread_group(detpid)
            .into_iter()
            .any(|tid| self.next_turns.contains_key(&tid));
