2708	    /// Keep scheduling inside an active vfork until the parent can continue.
2709	    /// Before child registration no guest may run; afterward step 3 admits only
2710	    /// the child. A failed clone reaches the parent continuation without a child.
2711	    ///
2712	    /// On the ptrace backend the kernel keeps the vfork parent blocked inside the injected
2713	    /// `clone(2)` until the child execs or exits, so a registered child (barrier `Some`) is always
2714	    /// present by the time the parent posts its continuation; an unfulfilled barrier (`None`) at
2715	    /// that point therefore means the clone failed and the barrier must be dropped. On a backend
2716	    /// that defers the child spawn (see `backend_defers_vfork_child_registration`, e.g. KVM) the
2717	    /// child registers only *after* the parent posts its continuation, so an unfulfilled barrier at
2718	    /// parent continuation means the child is still on its way and the barrier must be kept.
2719	    fn step2a_wait_for_vfork_barrier(&mut self) -> Result<(), SkipTurn> {
2720	        // AUTONOMOUS-BOT-IMPLEMENTED
2721	        // TODO-HUMAN-REVIEW(PR-1152): Review deferred vfork child registration.
2722	        let defers_registration = self.backend_defers_vfork_child_registration;
2723	        let completed_parents: Vec<_> = self
2724	            .vfork_barriers
2725	            .iter()
2726	            .filter_map(|(parent, registered_child)| {
2727	                let child_registered = registered_child.is_some();
2728	                let remove = match self
2729	                    .next_turns
2730	                    .get(parent)
2731	                    .and_then(|turn| turn.req.try_read())
2732	                {
2733	                    // The parent exited: there will be no child; drop the barrier.
2734	                    Some(Err(ThreadExited)) => true,
2735	                    Some(Ok(resources)) => {
2736	                        let vfork_failed = resources
2737	                            .resources
2738	                            .keys()
2739	                            .any(|resource| matches!(resource, ResourceID::VforkFailed(_)));
2740	                        let at_continue = resources.resources.keys().any(|resource| {
2741	                            matches!(resource, ResourceID::BlockedExternalContinue(_))
2742	                        });
2743	                        // A failed injected clone is an explicit deterministic outcome: no child
2744	                        // can ever register, so cancel the barrier on every backend. Successful
2745	                        // deferred spawns retain the ordinary continuation and keep waiting.
2746	                        // At parent continuation, drop a fulfilled barrier as normal cleanup. An
2747	                        // unfulfilled barrier is a failed clone only when the backend kept the
2748	                        // parent blocked until the child registered; when the backend defers child
2749	                        // registration the child is still coming, so keep waiting.
2750	                        vfork_failed || (at_continue && (child_registered || !defers_registration))
2751	                    }
2752	                    _ => false,
2753	                };
2754	                remove.then_some(*parent)
2755	            })
2756	            .collect();
2757	        for parent in completed_parents {
2758	            self.vfork_barriers.remove(&parent);
2759	        }
2760	
2761	        if self.vfork_barriers.values().all(Option::is_some) {
2762	            Ok(())
2763	        } else {
2764	            trace!(
2765	                "waiting for vfork child registration from parents {:?}",
2766	                self.vfork_barriers
2767	            );
2768	            Err(SkipTurn)
2769	        }
2770	    }
