4268	    /// Inner helper for just the core priority changing.
4269	    fn requeue_with_new_priority(&mut self, dettid: DetTid, new_priority: Priority) {
4270	        // TODO: do we want to record in preemption_writer if we are in schedule-trace-replay mode?
4271	        assert!(runqueue::is_ordinary_priority(new_priority));
4272	        // Alter the threads priority and requeue.
4273	        let _old_priority = self.priorities.insert(dettid, new_priority);
4274	        let present = self.run_queue.remove_tid(dettid);
4275	        if present {
4276	            self.runqueue_push_back(dettid); // Repush with new priority
4277	        }
4278	        trace!(
4279	            "[dettid {}] requeue: Priority mapping after change to priority {}: {:?}",
4280	            dettid, new_priority, self.priorities
4281	        );
4282	    }
