4403	    /// Tick global logical time due to represent the work of the scheduler itself.
4404	    /// Also, update committed time.
4405	    /// Prerequisite: all threads are parked, with their time contributions frozen.
4406	    fn bump_global_time(
4407	        &mut self,
4408	        global_time: &Mutex<GlobalTime>,
4409	        last_turn: &Result<Resources, SkipTurn>,
4410	    ) {
4411	        // An internal IO-polling retry (see `is_polling_turn`) must still advance logical
4412	        // time -- finite poll/epoll/select/futex timeouts are enforced by comparing observed
4413	        // logical time against the deadline in `retry_nonblocking_syscall_helper`, so freezing
4414	        // time here would turn a timed wait into an infinite spin. But because the *count* of
4415	        // these retries is host-timing nondeterministic, we keep their time-advance out of the
4416	        // determinism log (DETLOG). This makes the `--verify` deterministic comparison
4417	        // insensitive to retry count; the matching `{InternalIOPolling: ...}` COMMIT turn is
4418	        // likewise excluded in `logdiff::is_internal_io_poll_commit`. Time values still shift
4419	        // between runs, but those are numerically normalized before comparison.
4420	        let last_turn_was_polling = last_turn
4421	            .as_ref()
4422	            .map(|resources| {
4423	                Self::is_polling_turn(resources)
4424	                    || self.is_sabre_internal_pipe_io_turn(resources)
4425	                    || self.is_sabre_loopback_poll_yield_turn(resources)
4426	            })
4427	            .unwrap_or(false);
4428	
4429	        // At this moment, when threads are parked, we know that the global_time is
4430	        // frozen and we can read it without any race.
4431	        let snapshot: LogicalTime = {
4432	            let mut gtime = global_time.lock().unwrap();
4433	
4434	            if self.run_queue.is_empty() && self.blocked.only_external_blocked() {
4435	                // TODO(T112017687): rationalize the occurence of
4436	                // BlockingExternalIO in strict runs. For example, we should
4437	                // probably inject nanosleep and actually wait the intervening
4438	                // time, so we don't appear too fast to external observers.
4439	                trace!(
4440	                    "[scheduler] skipping scheduler time advance because we're ONLY waiting for external events"
4441	                );
4442	            } else if last_turn.is_err() {
4443	                // Note: if the last turn was a skip, it shouldn't really have time-bumped. But since we
4444	                // can't see the future, we just cancel out the bump by not doing a bump this turn.
4445	                trace!(
4446	                    "[scheduler] skipping scheduler time advance because just-finished turn did not progress (i.e. SkipTurn)"
4447	                );
4448	            } else if last_turn
4449	                .as_ref()
4450	                .map(Self::is_internal_turn)
4451	                .unwrap_or(false)
4452	            {
4453	                trace!(
4454	                    "[scheduler] skipping scheduler time advance because just-finished turn was an internal book-keeping one"
4455	                );
4456	            } else {
4457	                let newtime = gtime.add_scheduler_time();
4458	                if last_turn_was_polling {
4459	                    // Advance time (needed for timeout enforcement) but keep it off the DETLOG.
4460	                    trace!(
4461	                        "[sched] advance global time for internal IO-polling retry (suppressed from detlog), new time {:?}",
4462	                        newtime,
4463	                    );
4464	                } else {
4465	                    detlog_debug!(
4466	                        "[sched] advance global time for scheduler turn, new time {:?}",
4467	                        newtime,
4468	                    );
4469	                }
4470	            }
4471	            gtime.as_nanos()
4472	        };
4473	
4474	        match snapshot.cmp(&self.committed_time) {
4475	            std::cmp::Ordering::Less => {
4476	                panic!(
4477	                    "bump_global_time: invariant broken, global time went backwards from {} to {}",
4478	                    self.committed_time, snapshot
4479	                );
4480	            }
4481	            std::cmp::Ordering::Equal => {}
4482	            std::cmp::Ordering::Greater => {
4483	                // NB: `committed_time` still tracks the (host-timing-perturbed) global clock,
4484	                // including the time advanced by suppressed IO-polling retries above, so this
4485	                // line's presence is retry-count sensitive. It is therefore excluded from the
4486	                // deterministic `--verify` comparison in `logdiff::is_scheduler_committed_time`
4487	                // (it is redundant with the per-turn "advance global time" DETLOG anyway).
4488	                detlog_debug!(
4489	                    event = crate::detlog::DetLogEvent::SchedulerCommittedTime;
4490	                    "[sched-step1] advancing committed_time from {} to {}",
4491	                    self.committed_time,
4492	                    snapshot
4493	                );
4494	                self.committed_time = snapshot;
4495	            }
4496	        }
4497	    }
