4499	    /// Step 4: unblock enabled actions to actually, physically run.
4500	    fn step5_guest_unblock(
4501	        &mut self,
4502	        next_dtid: DetTid,
4503	        rsrcs: &Resources,
4504	        resp: &Ivar<SchedResponse>,
4505	    ) -> Result<(), SkipTurn> {
