5740	    /// F1/F2: an admission deferred while a tentative_pop window is live must
5741	    /// resolve its side -- including the `RunsPostFork::Random` PRNG draw -- at
5742	    /// the `DetTid`-ordered drain, so the drained run queue is a pure function of
5743	    /// deterministic state, independent of the order in which racing handlers
5744	    /// buffered the admissions.
5745	    #[test]
5746	    fn deferred_admission_side_is_arrival_order_independent() {
5747	        let config = Config {
5748	            sched_seed: Some(0xABCD),
5749	            runs_post_fork: RunsPostFork::Random,
5750	            ..Default::default()
5751	        };
5752	        let lower = DetTid::from_raw(21);
5753	        let higher = DetTid::from_raw(23);
5754	
5755	        // Buffer the two children in `order`, optionally while a tentative
5756	        // window is live, then drain. Return the drained relative order of the
5757	        // two children (the anchor is filtered out because it is consumed by the
5758	        // window in the `open_window` case but not otherwise -- what must be
5759	        // deterministic is the children's order and chosen sides).
5760	        let drained_order = |order: [DetTid; 2], open_window: bool| -> Vec<DetTid> {
5761	            let mut sched = Scheduler::new(&config);
5762	            let anchor = DetTid::from_raw(5);
5763	            register_known_thread(&mut sched, anchor);
5764	            sched.runqueue_push_back(anchor);
5765	            register_known_thread(&mut sched, lower);
5766	            register_known_thread(&mut sched, higher);
5767	
5768	            if open_window {
5769	                assert_eq!(sched.run_queue.tentative_pop_next(), Some(anchor));
5770	                assert!(sched.run_queue.tentative_pop_in_progress());
5771	            }
5772	            for tid in order {
5773	                sched.admit_to_run_queue(tid, AdmitIntent::PostFork(RunsPostFork::Random));
5774	            }
5775	            // Admission ALWAYS defers -- window or not -- so nothing is pushed or
5776	            // resolved (no side chosen, no PRNG drawn) until the drain.
5777	            assert!(sched.pending_run_queue_admissions.contains_key(&lower));
5778	            assert!(sched.pending_run_queue_admissions.contains_key(&higher));
5779	            assert!(!sched.run_queue.contains_tid(lower));
5780	            assert!(!sched.run_queue.contains_tid(higher));
5781	
5782	            if open_window {
5783	                let _ = sched.run_queue.commit_tentative_pop();
5784	            }
5785	            sched.drain_pending_run_queue_admissions();
5786	            sched
5787	                .run_queue
5788	                .tids()
5789	                .copied()
5790	                .filter(|t| *t == lower || *t == higher)
5791	                .collect()
5792	        };
5793	
5794	        // The drained order/side is independent of BOTH host-timing inputs the
5795	        // old immediate path was sensitive to: the arrival (buffering) order of
5796	        // the racing handlers, and whether a tentative window happened to be
5797	        // live when each handler ran.
5798	        let baseline = drained_order([lower, higher], true);
5799	        assert_eq!(
5800	            baseline,
5801	            drained_order([higher, lower], true),
5802	            "arrival order"
5803	        );
5804	        assert_eq!(
5805	            baseline,
5806	            drained_order([lower, higher], false),
5807	            "window state"
5808	        );
5809	        assert_eq!(baseline, drained_order([higher, lower], false), "both");
5810	        assert!(baseline.contains(&lower) && baseline.contains(&higher));
5811	    }
