7789	    /// report must not depend on insertion order, because `futex_waiters` is a
7790	    /// `HashMap`, `timed_out_futex_waiters` a `HashSet`, and
7791	    /// `Resources::resources` a `HashMap`.
7792	    fn deadlocked_scheduler(config: &Config, reverse: bool) -> Scheduler {
7793	        let mut scheduler = Scheduler::new(config);
