8359	              "events": {
8360	                "main_write":   {"thread": "main",   "syscalls": 47},
8361	                "worker_write": {"thread": "worker", "syscalls": 8}
8362	              },
8363	              "edges": [ {"before": "main_write", "after": "worker_write", "strength": "hard"} ]
8364	            }"#,
8365	        );
8366	        let main = DetTid::from_raw(3);
8367	        let worker = DetTid::from_raw(5);
8368	
8369	        // Anchors resolve to the addressed (thread, count) and nothing else.
8370	        assert_eq!(
8371	            hb.anchors_at_syscall(main, 47),
8372	            vec!["main_write".to_string()]
8373	        );
8374	        assert_eq!(
8375	            hb.anchors_at_syscall(worker, 8),
8376	            vec!["worker_write".to_string()]
8377	        );
8378	        assert!(hb.anchors_at_syscall(main, 8).is_empty());
8379	        assert!(hb.anchors_at_syscall(worker, 47).is_empty());
8380	        assert!(hb.anchors_at_syscall(worker, 7).is_empty());
8381	
