150	struct ProcessExitState {
151	    last_thread: Option<ExitStatus>,
152	    group: Option<ExitStatus>,
153	    failed: bool,
154	}
155	
156	impl TaskLifecycleTable {
157	    pub(crate) fn with_root(tid: i32, tgid: i32, pgid: i32, dumpable: bool) -> Self {
158	        let mut table = Self::default();
159	        table.register(tid, tgid, pgid, dumpable);
160	        table
161	    }
162	
163	    pub(crate) fn register(&mut self, tid: i32, tgid: i32, pgid: i32, dumpable: bool) -> u64 {
164	        self.next_generation = self
165	            .next_generation
166	            .checked_add(1)
167	            .expect("KVM task generation exhausted");
168	        let generation = self.next_generation;
169	        let process_generation = if tid == tgid {
170	            generation
171	        } else {
172	            self.tasks
173	                .values()
174	                .find(|task| task.tgid == tgid)
175	                .map_or(generation, |task| task.process_generation)
176	        };
177	        self.tasks.insert(
178	            tid,
179	            TaskLifecycleState {
180	                generation,
181	                process_generation,
182	                tgid,
183	                pgid,
184	                robust_list_head: 0,
185	                dumpable,
186	            },
187	        );
188	        // A reused numeric TID never inherits the old task's signal endpoint.
189	        self.signal_targets.remove(&tid);
190	        generation
191	    }
192	
193	    pub(crate) fn register_with_signals(
194	        &mut self,
195	        tid: i32,
196	        tgid: i32,
197	        pgid: i32,
198	        dumpable: bool,
199	        signals: &SharedThreadSignalState,
200	    ) -> u64 {
201	        let generation = self.register(tid, tgid, pgid, dumpable);
202	        self.signal_targets.insert(tid, signals.downgrade());
203	        generation
204	    }
205	
206	    pub(crate) fn ensure_registered_with_signals(
207	        &mut self,
208	        tid: i32,
209	        tgid: i32,
210	        pgid: i32,
211	        dumpable: bool,
212	        signals: &SharedThreadSignalState,
213	    ) -> u64 {
214	        let generation = self.ensure_registered(tid, tgid, pgid, dumpable);
215	        self.signal_targets.insert(tid, signals.downgrade());
216	        generation
217	    }
218	
219	    /// The caller keeps the lifecycle lock through queue publication, so an
220	    /// accepted send belongs to this incarnation even if the numeric TID is
221	    /// reused immediately after the lock is released.
222	    pub(crate) fn signal_target(&self, tid: i32) -> Option<SharedThreadSignalState> {
223	        self.signal_targets
224	            .get(&tid)
225	            .and_then(SharedThreadSignalState::upgrade)
226	    }
227	
228	    pub(crate) fn ensure_registered(
229	        &mut self,
230	        tid: i32,
231	        tgid: i32,
232	        pgid: i32,
233	        dumpable: bool,
234	    ) -> u64 {
235	        self.tasks
236	            .get(&tid)
237	            .map(|task| task.generation)
238	            .unwrap_or_else(|| self.register(tid, tgid, pgid, dumpable))
239	    }
240	
241	    pub(crate) fn remove(&mut self, tid: i32, generation: u64) {
242	        if self
243	            .tasks
244	            .get(&tid)
245	            .is_some_and(|task| task.generation == generation)
246	        {
247	            self.tasks.remove(&tid);
248	            self.signal_targets.remove(&tid);
249	        }
250	    }
251	
252	    /// Commit a guest task's exit while retiring its exact identity. Host
253	    /// handle completion and failed child preparation do not select a status.
254	    pub(crate) fn exit(
255	        &mut self,
256	        tid: i32,
257	        generation: u64,
258	        status: ExitStatus,
259	        group: bool,
260	    ) -> (ExitStatus, bool) {
261	        let Some(task) = self.tasks.get(&tid).copied() else {
262	            return (status, false);
263	        };
264	        if task.generation != generation {
265	            return (status, false);
266	        }
267	        let exit = self
268	            .process_exits
269	            .entry((task.tgid, task.process_generation))
270	            .or_default();
271	        let group_started = group && exit.group.is_none();
272	        if group_started {
273	            exit.group = Some(status);
274	        }
275	        exit.last_thread = Some(status);
276	        let status = exit.group.unwrap_or(status);
277	        self.remove(tid, generation);
278	        (status, group_started)
279	    }
280	
281	    pub(crate) fn process_exit_status(
282	        &self,
283	        tgid: i32,
284	        process_generation: u64,
285	    ) -> Option<ExitStatus> {
286	        if self
287	            .tasks
288	            .values()
289	            .any(|task| task.tgid == tgid && task.process_generation == process_generation)
290	        {
291	            return None;
292	        }
293	        let exit = self.process_exits.get(&(tgid, process_generation))?;
294	        if exit.failed {
295	            None
296	        } else {
297	            exit.group.or(exit.last_thread)
298	        }
299	    }
300	
301	    pub(crate) fn forget_process_exit(&mut self, tgid: i32, process_generation: u64) {
302	        if !self
303	            .tasks
304	            .values()
305	            .any(|task| task.tgid == tgid && task.process_generation == process_generation)
306	        {
307	            self.process_exits.remove(&(tgid, process_generation));
308	        }
309	    }
310	
311	    pub(crate) fn fail(&mut self, tid: i32, generation: u64) -> bool {
312	        let Some(task) = self.tasks.get(&tid).copied() else {
313	            return false;
314	        };
315	        if task.generation != generation {
316	            return false;
317	        }
318	        self.process_exits
319	            .entry((task.tgid, task.process_generation))
320	            .or_default()
321	            .failed = true;
322	        self.remove(tid, generation);
323	        true
324	    }
325	
326	    pub(crate) fn reset_after_exec(&mut self, tid: i32, tgid: i32, pgid: i32) -> u64 {
327	        if let Some(task) = self.tasks.get_mut(&tid) {
328	            self.process_exits
329	                .remove(&(task.tgid, task.process_generation));
330	            task.tgid = tgid;
331	            task.pgid = pgid;
332	            task.robust_list_head = 0;
333	            task.dumpable = true;
334	            task.generation
335	        } else {
336	            self.register(tid, tgid, pgid, true)
337	        }
338	    }
339	
340	    pub(crate) fn reset_after_exec_with_signals(
341	        &mut self,
342	        tid: i32,
343	        tgid: i32,
344	        pgid: i32,
345	        signals: &SharedThreadSignalState,
346	    ) -> u64 {
347	        let generation = self.reset_after_exec(tid, tgid, pgid);
348	        self.signal_targets.insert(tid, signals.downgrade());
349	        generation
350	    }
351	
352	    pub(crate) fn set_robust_list(&mut self, tid: i32, head: u64) -> bool {
353	        let Some(task) = self.tasks.get_mut(&tid) else {
354	            return false;
355	        };
356	        task.robust_list_head = head;
357	        true
358	    }
359	
360	    pub(crate) fn get(&self, tid: i32) -> Option<TaskLifecycleState> {
361	        self.tasks.get(&tid).copied()
362	    }
363	
364	    /// Exact live task identities in one process lifetime, in stable TID order.
365	    pub(crate) fn signal_process_tasks(
366	        &self,
